"""Aggregate both reviews and route: publish on a pass, revise on a rejection."""
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[2]


def nodemain_gate(inputs):
    failed = []
    if not inputs["style_passed"]:
        failed.append("style")
    if not inputs["consistency_passed"]:
        failed.append("consistency")
    passed = not failed
    notes = ROOT / "review-notes.md"
    if passed:
        notes.write_text("Both reviews passed.\n", encoding="utf-8")
    else:
        notes.write_text(
            "Revise the draft; these reviews rejected it: " + ", ".join(failed) + ".\n",
            encoding="utf-8",
        )
    return json.dumps(
        {"passed": passed, "failed": failed, "notes_file": str(notes)},
        ensure_ascii=False,
    )
